from pathlib import Path
for name in ['replica.css','contents.css']:
 p=Path('app/src')/name
 s=p.read_text(encoding='utf-8')
 p.write_text('@layer components {\n'+s+'\n}\n',encoding='utf-8')
p=Path('app/src/Replica.jsx')
s=p.read_text(encoding='utf-8')
s=s.replace("import {WithContents} from './TableOfContents';", "import {WithContents} from './TableOfContents';\nimport {Prose} from './Prose';")
s=s.replace('className="profile-copy"','className="profile-copy max-w-[62ch] text-pretty text-[0.9375rem] leading-[1.8] sm:text-base"')
s=s.replace('<h1 data-entrance="2">','<h1 className="text-balance leading-[1.12] tracking-[-0.05em]" data-entrance="2">')
