s=s.replace('<p data-entrance="2">{children}</p>','<p className="max-w-[62ch] text-pretty text-base leading-[1.8] sm:text-[1.0625rem]" data-entrance="2">{children}</p>')
s=s.replace('<p>I\'m Rahmawan, a <strong>front-end developer</strong> who loves imagining and creating beautiful designs and applications.</p>', '<Prose className="mb-4 max-w-[60ch] text-sm sm:text-sm"><p>I\'m Rahmawan, a <strong>front-end developer</strong> who loves imagining and creating beautiful designs and applications.</p></Prose>')
s=s.replace('<h3>{item.role}</h3>','<h3 className="text-balance leading-snug tracking-[-0.025em]">{item.role}</h3>')
